import { useState } from 'react';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { AS_OF_PARAM } from './useAsOf';

// Sets or clears the signed-in user's as-of date, and shows it (nothing when none). While it is set the whole screen
// shows the sheet as it stood at the end of that date and every change is refused; it is this screen's alone.
export function AsOfControl() {
  const [asOf, setAsOf] = useSearchParam(AS_OF_PARAM, asString);
  const [date, setDate] = useState('');
  return (
    <form
      data-testid="asof-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = date.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) setAsOf(trimmed);
      }}
    >
      As of: <span data-testid="sheet-asof">{asOf}</span>{' '}
      <input type="date" data-testid="asof-date" value={date} onChange={(e) => setDate(e.target.value)} />
      <button type="submit" data-testid="asof-set">Set as-of</button>
      <button type="button" data-testid="asof-clear" onClick={() => setAsOf(undefined)}>
        Clear as-of
      </button>
    </form>
  );
}
import { createContext, useContext } from 'react';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** The URL key holding the signed-in user's as-of date ("" or absent: none, the live sheet). It is this screen's
 *  alone: other users, and the store, are unaffected. */
export const AS_OF_PARAM = 'asof';

/** The as-of date the screen is shown at (YYYY-MM-DD), "" for none. While it is set every read is of the sheet as
 *  it stood at the end of that date, the date standing for the sheet's today, and every change is refused. */
export function useAsOf(): string {
  const [asOf] = useSearchParam(AS_OF_PARAM, asString);
  return useContext(LiveReads) ? '' : asOf;
}

/** While true, the reads below it are of the live sheet whatever the as-of date (see features/consolidated). */
export const LiveReads = createContext(false);

/** A read's path, asking for the sheet as of the date when one is set. */
export function readPath(path: string, asOf: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

export type SheetToday = { sheet: string; today: string; archived: boolean };

export const sheetTodayKey = (sheet: string, asOf = '') => ['sheet', sheet, 'today', asOf] as const;

/** The sheet's today (YYYY-MM-DD; the as-of date while one is set). Every date decision and default date on screen reads this —
 *  never `new Date()`. Undefined while loading. */
export function useSheetToday(sheet: string): string | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.today;
}

/** Whether the sheet is archived (everything visible, every change refused). Undefined while loading. */
export function useSheetArchived(sheet: string): boolean | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.archived;
}
import { useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useSettings } from '../settings/useSettings';
import { sheetTodayKey, useSheetArchived, useSheetToday, type SheetToday as SheetTodayDto } from './useSheetToday';

// Shows the active sheet's today and changes it. A blank date resets it to the real date.
// Also shows whether the sheet is archived, and archives it (a steward only), and its parent sheet (nothing when none),
// and clones it to another id never used (a steward only), showing the id cloned to once done.
export function SheetToday() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const today = useSheetToday(sheet);
  const archived = useSheetArchived(sheet);
  const settings = useSettings(sheet);
  const [date, setDate] = useState('');
  const [cloneTo, setCloneTo] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (value: string) =>
      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today: value, user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
      // Everything on the sheet may depend on its date: re-read it all.
      void queryClient.invalidateQueries({ queryKey: ['sheet', saved.sheet] });
    },
  });
  const archive = useMutation({
    mutationFn: () =>
      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
    },
  });
  const clone = useMutation({
    mutationFn: (to: string) =>
      postJson<{ sheet: string; toSheet: string }>(`/api/sheets/${encodeURIComponent(sheet)}/clone`, { toSheet: to, user }),
  });
  const resetAll = () => {
    save.reset();
    archive.reset();
    clone.reset();
  };
  const { reset: resetClone } = clone;
  // A clone made from another sheet is not this one's.
  useEffect(() => resetClone(), [sheet, resetClone]);
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        clone.reset();
        submitOnce(() => save.mutateAsync(date.trim()));
      }}
    >
      Today: <span data-testid="sheet-today">{today ?? ''}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          resetAll();
        }}
      />
      <button type="submit" data-testid="sheet-today-save">Set today</button>
      {' '}Parent: <span data-testid="sheet-parent">{settings?.parent ?? ''}</span>
      {' '}Archived: <span data-testid="sheet-archived">{archived === undefined ? '' : archived ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        onClick={() => {
          resetAll();
          submitOnce(() => archive.mutateAsync());
        }}
      >
        Archive sheet
      </button>
      {' '}Clone to:{' '}
      <input
        data-testid="sheet-clone-to"
        value={cloneTo}
        onChange={(e) => {
          setCloneTo(e.target.value);
          resetAll();
        }}
      />
      <button
        type="button"
        data-testid="sheet-clone"
        onClick={() => {
          resetAll();
          submitOnce(() => clone.mutateAsync(cloneTo.trim()));
        }}
      >
        Clone sheet
      </button>{' '}
      <span data-testid="sheet-cloned-to">{clone.data?.toSheet ?? ''}</span>
      {save.isError && <span data-testid="sheet-error" role="alert"> Could not change today.</span>}
      {archive.isError && <span data-testid="sheet-error" role="alert"> Could not archive the sheet.</span>}
      {clone.isError && <span data-testid="sheet-error" role="alert"> Could not clone the sheet.</span>}
    </form>
  );
}
import { createFileRoute } from '@tanstack/react-router';
import { asString, useSearchParam } from '../url/useSearchParam';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { LocaleControl } from '../features/locale/LocaleControl';
import { SheetPicker } from '../features/session/SheetPicker';
import { SheetToday } from '../features/sheet/SheetToday';
import { AsOfControl } from '../features/asof/AsOfControl';
import { RatePanel } from '../features/rates/RatePanel';
import { HolidayPanel } from '../features/holidays/HolidayPanel';
import { GradePanel } from '../features/grades/GradePanel';
import { VoidReasonPanel } from '../features/voidreasons/VoidReasonPanel';
import { NotePanel } from '../features/notes/NotePanel';
import { PoolPanel } from '../features/pools/PoolPanel';
import { CrewPanel } from '../features/crews/CrewPanel';
import { TemplatePanel } from '../features/templates/TemplatePanel';
import { SettingsPanel } from '../features/settings/SettingsPanel';
import { PeriodPanel } from '../features/periods/PeriodPanel';
import { PersonForm } from '../features/people/PersonForm';
import { PeopleList } from '../features/people/PeopleList';
import { DuplicateClaims } from '../features/claims/DuplicateClaims';
import { SheetHeader } from '../features/header/SheetHeader';
import { StewardDashboard } from '../features/dashboard/StewardDashboard';
import { ConsolidatedFigures } from '../features/consolidated/ConsolidatedFigures';
import { TreeSearch } from '../features/search/TreeSearch';
import { AuditViewer } from '../features/audit/AuditViewer';
import { ActivityPanel } from '../features/audit/ActivityPanel';

// The one screen. Signed out it shows only the sign-in form; signed in, the user and the sheet
// picker, and — once a sheet is loaded — that sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useSearchParam('user', asString);
  const [sheet] = useSearchParam('sheet', asString);
  if (user === '') return <SignIn />;
  return (
    <>
      <CurrentUser />
      <LocaleControl />
      <SheetPicker />
      {sheet !== '' && (
        <div key={sheet}>
          <SheetHeader />
          <StewardDashboard />
          <SheetToday />
          <ConsolidatedFigures />
          <AsOfControl />
          <RatePanel />
          <GradePanel />
          <HolidayPanel />
          <VoidReasonPanel />
          <NotePanel />
          <TemplatePanel />
          <SettingsPanel />
          <PeriodPanel />
          <PersonForm />
          <PeopleList />
          <DuplicateClaims />
          <PoolPanel />
          <CrewPanel />
          <TreeSearch />
          <AuditViewer />
          <ActivityPanel />
        </div>
      )}
      {sheet === '' && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
  );
}
