import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { usePersonAction } from '../people/usePersonAction';
import { claimsKey } from '../claims/useClaims';
import { peopleKey, type Person } from '../people/usePeople';

// Takes a statement for the person: the server records their due-total now and binds each of their
// counting claims to its figure now (the rest are left unbound). With a date beside the button (on or
// before the sheet's today; blank: now) the statement is taken as of the end of that date; the date is cleared
// once the statement is taken or refused. A refusal shows the person's error.
export function StatementButton({ personId }: { personId: string }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [asOf, setAsOf] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const take = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/statement`, {
        user,
        asOf: date,
      }),
    // The date is used for this statement alone, taken or refused: the next one is now unless a date is given again.
    onSettled: () => setAsOf(''),
    onSuccess: () => {
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
  });
  const taken = usePersonAction(personId, () => take.reset());

  return (
    <>
      <input
        type="date"
        data-testid="person-statement-asof"
        value={asOf}
        title="Statement as of (blank: now)"
        onChange={(e) => {
          setAsOf(e.target.value);
          take.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-statement"
        onClick={() => {
          taken();
          once(() => take.mutateAsync(asOf.trim()));
        }}
      >
        Statement
      </button>
      {take.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          The statement could not be taken.
        </span>
      )}
    </>
  );
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimResponse;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement: the person's due-total as the screen shows it now (the sum of their counting
 * claims' dues — each fixed or at the rate in force on its date, its late charge on top, raised to the floor in force on its date;
 * n/a when their grade has no rate today and no claim keeps a figure; held to the sheet's cap less their cut total, not below 0.00), and binds each counting claim to
 * its due as shown now, its late charge and the floor included (a claim already bound keeps its bound figure); while bound
 * the claim shows and totals that figure, its late charge no longer following the sheet's today.
 * A claim that does not count (a deferred claim, or an unbound OPEN claim of a retired person, included) is left unbound.
 * <p>
 * Taken as of a date (on or before the sheet's today, and not before the person was added), the same is worked from the
 * store as it stood at the end of that date (see {@link AsOf}), that date standing in for the sheet's today: the claims
 * that counted then are bound to their figures then, the person's other claims are left unbound, and the statement is
 * dated that date.
 */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, AsOf asOf, Sheets sheets,
            People people, Settings settings, net.officefloor.hq.app.pool.Pools pools, Out<Statement> statement) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        LocalDate date = asOfDate(request, person, sheets.today(sheetId));
        AsOf.View view = date == null ? asOf.now(person) : asOf.at(person, date);
        LocalDate today = view.today();
        Person then = view.person();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        // The figure each counting claim is bound to, by id (a null figure: n/a).
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : view.claims()) {
            if (!then.countsLive(claim, today)) {
                continue;
            }
            RoundingMode rounding = Rounding.of(claim, view.policyDate(), view.rounding());
            BigDecimal fixed = ClaimResponse.fixedDue(claim);
            // A bound claim keeps its figure (even n/a); a live one is worked at the rate on its date (unfloored).
            BigDecimal figure = fixed != null || claim.isBound() ? fixed
                    : Rates.due(claim.getAmount(), view.rate().rate(then.gradeOn(claim.getDate()), claim.getDate(), claim.getRateMark()), rounding);
            if (figure != null) {
                anyFigure = true;
                figure = LateCharge.due(claim, figure, view.floor().apply(claim.getDate()), view.latePct(), today, rounding,
                        settings.grace(sheetId, then.gradeOn(claim.getDate()), claim.getDate()));
                total = total.add(figure);
            }
            bound.put(claim.getId(), figure);
            counted++;
        }
        for (Claim claim : date == null ? view.claims() : claims.ofPerson(sheetId, person.getId())) {
            claim.setStated(bound.containsKey(claim.getId()));
            claim.setStatedDue(bound.get(claim.getId()));
            claims.bind(claim);
        }
        // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
        boolean na = !anyFigure && view.rate().rate(then.getGrade(), today, Rates.IN_FORCE) == null;
        BigDecimal cutTotal = view.cap() == null ? null : pools.cutTotals(sheetId, date).getOrDefault(person.getId(), BigDecimal.ZERO);
        BigDecimal dueTotal = na ? null : Settings.capped(total, view.cap(), cutTotal);
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        people.addStatement(person);

